function initials(name: string): string {
  const parts = name.trim().split(/\s+/);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name.slice(0, 2).toUpperCase();
}

function courseProgress(courseId: string, completions: string[]): number {
  const total = chapterSets[courseId]?.length ?? 1;
  const done = (chapterSets[courseId] ?? []).filter((ch) => completions.includes(ch.id)).length;
  return Math.round((done / total) * 100);
}

function overallProgress(completions: string[]): number {
  const all = Object.keys(chapterSets).flatMap((id) => chapterSets[id]);
  const done = all.filter((ch) => completions.includes(ch.id)).length;
  return Math.round((done / all.length) * 100);
}

function averageScore(results: { score: number }[]): number {
  if (results.length === 0) return 0;
  return Math.round(results.reduce((sum, r) => sum + r.score, 0) / results.length);
}

function nextChapter(completions: string[]): { course: Course; chapter: Chapter } | null {
  for (const courseId of Object.keys(chapterSets)) {
    const chapters = chapterSets[courseId] ?? [];
    const next = chapters.find((ch) => !completions.includes(ch.id) && ch.status !== 'locked');
    if (next) {
      const course = courses.find((c) => c.id === courseId)!;
      return { course, chapter: next };
    }
  }
  return null;
}

function courseAverageScore(results: { score: number; course_id: string }[], courseId: string): number {
  const courseResults = results.filter((r) => r.course_id === courseId);
  return averageScore(courseResults);
}

