const viewFromPath = (): View => {
  const key = window.location.pathname.split('/')[1] as View;
    return ['dashboard', 'courses', 'course', 'learn', 'test', 'result', 'midterm', 'final', 'progress', 'profile', 'admin', 'login', 'register'].includes(key) ? key : 'home';
};

function pathParts(): string[] { return window.location.pathname.split('/').filter(Boolean); }

function navigate(view: View, id?: string): void {
  const path = id ? `/${view}/${id}` : `/${view}`;
  window.history.pushState({}, '', path);
  window.dispatchEvent(new PopStateEvent('popstate'));
}

function App() {
  const { session, user, profile, loading, signOut } = useAuth();
  const [view, setView] = useState<View>(viewFromPath());
  const [activeCourse, setActiveCourse] = useState(() => pathParts()[1] ?? 'oop');
    const [activeChapterId, setActiveChapterId] = useState(() => pathParts()[2] ?? 'oop-3');
  const [assessmentType, setAssessmentType] = useState<AssessmentType>(() => (pathParts()[2] === 'midterm' || pathParts()[2] === 'final' ? pathParts()[2] as AssessmentType : 'chapter'));
  const [mobileOpen, setMobileOpen] = useState(false);
  const [testScore, setTestScore] = useState({ score: 0, correct: 0, incorrect: 0, time: '00:00' });
  const [resultId, setResultId] = useState<number | null>(() => Number(pathParts()[2]) || null);
  const [, setCatalogVersion] = useState(0);

  const { completions, results, courseProgress: progressByCourse, toggleCompletion, saveTestResult } = useUserData(user?.id ?? null);

  useEffect(() => {
    api.courses().then(({ courses: remoteCourses }) => {
      remoteCourses.forEach((remote) => {
        const localCourse = courses.find((course) => course.id === remote.slug);
        if (!localCourse) return;
        localCourse.title = remote.title; localCourse.description = remote.description; localCourse.code = remote.code; localCourse.level = remote.level; localCourse.chapters = remote.chapters.length;
        chapterSets[remote.slug] = remote.chapters.map((chapter) => ({ id: chapter.slug, number: String(chapter.number).padStart(2, '0'), title: chapter.title, description: chapter.description, status: chapter.status as Chapter['status'], progress: 0, duration: '2 lectures' }));
      });
      setCatalogVersion((version) => version + 1);
    }).catch(() => undefined);
  }, []);

  useEffect(() => {
    const handlePop = (): void => {
      const parts = pathParts();
      setView(viewFromPath());
      if (parts[1]) setActiveCourse(parts[1]);
      if (parts[0] === 'learn' && parts[2]) setActiveChapterId(parts[2]);
      if (parts[0] === 'test') setAssessmentType(parts[2] === 'midterm' || parts[2] === 'final' ? parts[2] : 'chapter');
      if (parts[0] === 'result') setResultId(Number(parts[2]) || null);
    };
    window.addEventListener('popstate', handlePop);
    return () => window.removeEventListener('popstate', handlePop);
  }, []);

  const openCourse = (id: string): void => { setActiveCourse(id); navigate('course', id); };
  const openLearn = (id = activeCourse, chapterId = `${id}-3`): void => { setActiveCourse(id); setActiveChapterId(chapterId); navigate('learn', `${id}/${chapterId}`); };
  useEffect(() => {
    const handleHeaderSearch = (event: MouseEvent): void => {
      const button = (event.target as HTMLElement).closest('.header-actions .icon-button');
      if (!button || button.classList.contains('notification')) return;
      const query = window.prompt('Search courses and chapters');
      if (!query) return;
      const match = courses.flatMap((course) => (chapterSets[course.id] ?? []).map((chapter) => ({ course, chapter }))).find(({ course, chapter }) => `${course.title} ${chapter.title} ${chapter.description}`.toLowerCase().includes(query.toLowerCase()));
      if (match) { setActiveCourse(match.course.id); setActiveChapterId(match.chapter.id); navigate('learn', `${match.course.id}/${match.chapter.id}`); } else navigate('courses');
    };
    document.addEventListener('click', handleHeaderSearch);
    return () => document.removeEventListener('click', handleHeaderSearch);
  }, [activeCourse]);
  const markComplete = (chapterId: string): void => {
    toggleCompletion(chapterId, activeCourse);
  };
  const submitTest = (result: Omit<Submission, 'type' | 'chapterId'>, type: AssessmentType): void => {
    setTestScore(result);
    const chapterId = type === 'chapter' ? activeChapterId : `${activeCourse}-${type}`;
    latestSubmission = { ...result, type, chapterId, resultId: result.resultId };
    saveTestResult({ course_id: activeCourse, chapter_id: chapterId, score: result.score, correct_answers: result.correct, incorrect_answers: result.incorrect, time_taken: result.time });
    navigate('result', result.resultId ? `${activeCourse}/${result.resultId}` : activeCourse);
  };

  if (loading) return <div style={{ minHeight: '100vh', display: 'grid', placeItems: 'center', color: '#68777c' }}><Loader2 size={28} className="spin" /></div>;

  if (view === 'home') return <Landing onNavigate={navigate} onCourse={openCourse} />;
  if (view === 'login' || view === 'register') return <Auth mode={view} onNavigate={navigate} />;

  if (!session) return <Auth mode="login" onNavigate={navigate} />;

  const displayName = profile?.full_name || user?.email?.split('@')[0] || 'Student';
  const userInitials = initials(displayName);

  return <AppShell view={view} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen} onNavigate={navigate} onCourse={openCourse} onSignOut={signOut} userName={displayName} userInitials={userInitials}>
    {view === 'dashboard' && <Dashboard onNavigate={navigate} onCourse={openCourse} completions={completions} results={results} userName={displayName} />}
    {view === 'courses' && <Courses onCourse={openCourse} progressByCourse={progressByCourse} />}
    {view === 'course' && <CourseDetail courseId={activeCourse} completed={completions} results={results} onBack={() => navigate('courses')} onLearn={openLearn} onNavigate={navigate} />}
    {view === 'learn' && <InteractiveLearn courseId={activeCourse} chapterId={activeChapterId} completed={completions} onComplete={() => markComplete(activeChapterId)} onNavigate={navigate} onSelectChapter={openLearn} />}
    {view === 'test' && <Test courseId={activeCourse} chapterId={activeChapterId} type={assessmentType} onSubmit={(result) => submitTest(result, assessmentType)} onNavigate={navigate} />}
    {view === 'result' && <ResultReview courseId={activeCourse} resultId={resultId} onNavigate={navigate} score={testScore} onCourse={openCourse} />}
    {view === 'midterm' && <Exam type="midterm" courseId={activeCourse} onNavigate={navigate} />}
    {view === 'final' && <Exam type="final" courseId={activeCourse} onNavigate={navigate} />}
    {view === 'progress' && <ProgressReport completions={completions} results={results} userName={displayName} />}
    {view === 'profile' && <ProfileEditor profile={profile} email={user?.email ?? ''} />}
    {view === 'admin' && <AdminPanel />}
  </AppShell>;
}

function Logo(): JSX.Element { return <button className="logo" onClick={() => navigate('home')}><span className="logo-mark"><Sparkles size={17} /></span><span>Code <b>Quest</b></span></button>; }

function SearchButton({ onCourse }: { onCourse: (id: string) => void }): JSX.Element {
  const [open, setOpen] = useState(false); const [query, setQuery] = useState('');
  const matches = courses.flatMap((course) => (chapterSets[course.id] ?? []).filter((chapter) => `${course.title} ${chapter.title} ${chapter.description}`.toLowerCase().includes(query.toLowerCase())).map((chapter) => ({ course, chapter })));
  return <><button className="icon-button" aria-label="Search courses and chapters" onClick={() => setOpen(true)}><Search size={18} /></button>{open && <div className="search-popover"><div className="search-field"><Search size={17} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search courses and chapters" /><button className="icon-button" onClick={() => setOpen(false)}><X size={16} /></button></div><div className="search-results">{query && matches.slice(0, 8).map(({ course, chapter }) => <button key={chapter.id} onClick={() => { onCourse(course.id); setOpen(false); }}><span className={`tiny-course-icon ${course.tone}`}>{course.icon}</span><span><b>{chapter.title}</b><small>{course.title} · Chapter {chapter.number}</small></span><ChevronRight size={14} /></button>)}{query && matches.length === 0 && <p>No matching course or chapter.</p>}</div></div>}</>;
}

