function CourseCard({ course, onClick, compact = false }: { course: Course; onClick: () => void; compact?: boolean }): JSX.Element { return <article className={`course-card tone-${course.tone} ${compact ? 'compact' : ''}`}><div className="card-top"><span className="course-icon">{course.icon}</span><span className="course-level">{course.level}</span></div><span className="course-code">{course.code}</span><h3>{course.title}</h3><p>{course.description}</p><div className="course-meta"><span>{course.chapters} chapters</span><span className="meta-dot" /><span>Chapter tests</span></div>{!compact && <div className="course-progress"><div className="progress-label"><span>Your progress</span><b>{course.progress}%</b></div><ProgressBar value={course.progress} tone={course.tone} /></div>}<button className="card-link" onClick={onClick}>View course <ChevronRight size={16} /></button></article>; }
function ProgressBar({ value, tone = 'cyan' }: { value: number; tone?: string }): JSX.Element { return <div className={`progress-track ${tone}`}><span style={{ width: `${value}%` }} /></div>; }

function AppShell({ children, view, mobileOpen, setMobileOpen, onNavigate, onCourse, onSignOut, userName, userInitials }: { children: ReactNode; view: View; mobileOpen: boolean; setMobileOpen: (value: boolean) => void; onNavigate: (view: View) => void; onCourse: (id: string) => void; onSignOut: () => void; userName: string; userInitials: string }): JSX.Element { const links: [View, string, ReactNode][] = [['dashboard', 'Overview', <LayoutDashboard />], ['courses', 'Courses', <BookOpen />], ['progress', 'Progress', <BarChart3 />], ['profile', 'Profile', <User />]]; return <div className="app-shell"><aside className={`sidebar ${mobileOpen ? 'open' : ''}`}><div className="sidebar-top"><Logo /><button className="icon-button close-sidebar" onClick={() => setMobileOpen(false)}><X /></button></div><div className="side-label">Learning space</div><nav className="side-nav">{links.map(([id, label, icon]) => <button key={id} className={view === id ? 'active' : ''} onClick={() => { onNavigate(id); setMobileOpen(false); }}>{icon}<span>{label}</span>{id === 'progress' && <span className="nav-dot" />}</button>)}</nav><div className="side-label course-label">Your courses</div><div className="side-courses">{courses.map((course) => <button key={course.id} onClick={() => { onCourse(course.id); setMobileOpen(false); }}><span className={`tiny-course-icon ${course.tone}`}>{course.icon}</span><span>{course.title.split(' ')[0]}{course.id === 'oop' ? ' Programming' : course.id === 'dsa' ? ' & Algorithms' : ' Systems'}</span><ChevronRight size={13} /></button>)}</div><div className="sidebar-bottom"><div className="upgrade-card"><Sparkles size={17} /><b>Stay curious.</b><p>Small steps compound into expertise.</p></div><button className="side-settings" onClick={onSignOut}><LogIn size={16} /> Sign out</button></div></aside><div className="main-shell"><header className="app-header"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(true)}><Menu /></button><div className="crumb"><span>Learning space</span><ChevronRight size={14} /><b>{view === 'dashboard' ? 'Overview' : view[0].toUpperCase() + view.slice(1)}</b></div><div className="header-actions"><button className="icon-button"><Search size={18} /></button><button className="icon-button notification"><CircleHelp size={18} /></button><button className="profile-chip" onClick={() => onNavigate('profile')}><span className="avatar">{userInitials}</span><span className="profile-name">{userName}</span><ChevronRight size={14} /></button></div></header><main className="app-content">{children}</main></div>{mobileOpen && <button className="sidebar-overlay" onClick={() => setMobileOpen(false)} aria-label="Close menu" />}</div>; }

function PageTitle({ eyebrow, title, text, action }: { eyebrow: string; title: string; text?: string; action?: ReactNode }): JSX.Element { return <div className="page-title"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{text && <p>{text}</p>}</div>{action}</div>; }
function Dashboard({ onNavigate, onCourse, completions, results, userName }: { onNavigate: (view: View) => void; onCourse: (id: string) => void; completions: string[]; results: { score: number; course_id: string; chapter_id: string; created_at: string }[]; userName: string }): JSX.Element {
  const overall = overallProgress(completions);
  const avgScore = averageScore(results);
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
  const next = nextChapter(completions);
  const nextCourse = next?.course ?? courses[0];
  const nextCh = next?.chapter;
  const nextProgress = nextCh ? nextCh.progress : 0;
  return <><PageTitle eyebrow={today} title={`Welcome back, ${userName.split(' ')[0]}`} text="Keep your momentum going. Your next quest is ready when you are." action={<button className="button button-primary" onClick={() => onCourse(nextCourse.id)}>Continue learning <ArrowRight size={16} /></button>} /><section className="welcome-strip"><div><span className="eyebrow light">NEXT UP</span><h2>{nextCh ? `Chapter ${nextCh.number} — ${nextCh.title}` : 'All caught up'}</h2><p>{nextCourse.title} <span>•</span> {nextCh?.duration ?? 'Review'}</p><button className="strip-link" onClick={() => onCourse(nextCourse.id)}>Resume quest <ArrowRight size={15} /></button></div><div className="strip-progress"><strong>{nextProgress}%</strong><span>chapter progress</span><ProgressBar value={nextProgress} /></div><div className="strip-art"><span>class</span><span>extends</span><span>override</span></div></section><div className="stats-grid"><MiniStat icon={<Target />} label="Overall progress" value={`${overall}%`} detail="Keep going" tone="cyan" /><MiniStat icon={<BookOpen />} label="Courses enrolled" value="03" detail="All paths active" tone="amber" /><MiniStat icon={<CheckCircle2 />} label="Chapters completed" value={String(completions.length).padStart(2, '0')} detail="Keep learning" tone="emerald" /><MiniStat icon={<BarChart3 />} label="Average score" value={`${avgScore}%`} detail={results.length > 0 ? `${results.length} tests taken` : 'No tests yet'} tone="rose" /></div><div className="dashboard-grid"><div className="dashboard-main"><div className="section-bar"><div><span className="eyebrow">Your courses</span><h2>Keep building your edge.</h2></div><button className="inline-link" onClick={() => onNavigate('courses')}>See all courses <ArrowRight size={15} /></button></div><div className="course-list">{courses.map((course) => <CourseRow key={course.id} course={{ ...course, progress: courseProgress(course.id, completions) }} onClick={() => onCourse(course.id)} />)}</div></div><aside className="activity-panel"><div className="section-bar"><div><span className="eyebrow">Recent activity</span><h2>Quest log</h2></div><button className="icon-button"><ArrowRight size={15} /></button></div>{results.slice(0, 4).map((r, i) => <Activity key={i} icon={<FileCheck2 />} title={`Chapter test — ${r.course_id.toUpperCase()}`} time={new Date(r.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} score={`${r.score}%`} tone="cyan" />)}{completions.length === 0 && results.length === 0 && <div style={{ padding: '20px 0', textAlign: 'center', color: '#94a1a1', fontSize: 11 }}>No activity yet. Start learning to see your quest log.</div>}<div className="achievement"><span className="achievement-icon"><ShieldCheck size={20} /></span><div><b>On a roll</b><p>Complete 2 more chapters to unlock your next milestone.</p></div></div></aside></div></>; }
function MiniStat({ icon, label, value, detail, tone }: { icon: ReactNode; label: string; value: string; detail: string; tone: string }): JSX.Element { return <div className={`mini-stat ${tone}`}><span className="mini-stat-icon">{icon}</span><span className="mini-stat-label">{label}</span><strong>{value}</strong><small>{detail}</small></div>; }
function CourseRow({ course, onClick }: { course: Course; onClick: () => void }): JSX.Element { return <div className="course-row"><span className={`course-icon small-icon ${course.tone}`}>{course.icon}</span><div className="course-row-info"><div><b>{course.title}</b><span>{course.chapters} chapters <i /> {course.level}</span></div><ProgressBar value={course.progress} tone={course.tone} /></div><strong className="row-percent">{course.progress}%</strong><button className="icon-button row-arrow" onClick={onClick}><ChevronRight size={17} /></button></div>; }
function Activity({ icon, title, time, score, tone }: { icon: ReactNode; title: string; time: string; score: string; tone: string }): JSX.Element { return <div className="activity"><span className={`activity-icon ${tone}`}>{icon}</span><div><b>{title}</b><small>{time}</small></div><strong>{score}</strong></div>; }
function Courses({ onCourse, progressByCourse }: { onCourse: (id: string) => void; progressByCourse: Record<string, number> }): JSX.Element { const [query, setQuery] = useState(''); const [remoteCourses, setRemoteCourses] = useState<Course[]>(courses); useEffect(() => { api.courses().then(({ courses: remote }) => setRemoteCourses(courses.map((local) => { const server = remote.find((item) => item.slug === local.id); return server ? { ...local, title: server.title, description: server.description, code: server.code, level: server.level, chapters: server.chapters.length } : local; }))).catch(() => undefined); }, []); const coursesWithProgress = useMemo(() => remoteCourses.map((course) => ({ ...course, progress: progressByCourse[course.id] ?? 0 })), [progressByCourse, remoteCourses]); const filtered = useMemo(() => coursesWithProgress.filter((course) => course.title.toLowerCase().includes(query.toLowerCase())), [query, coursesWithProgress]); return <><PageTitle eyebrow="Course library" title="Choose your next challenge." text="Three focused paths. A clear route from foundations to fluency." /><div className="course-toolbar"><div className="search-field"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search courses" /></div><span className="result-count">{filtered.length} courses available</span></div><div className="course-grid app-course-grid">{filtered.map((course) => <CourseCard key={course.id} course={course} onClick={() => onCourse(course.id)} />)}</div><div className="assessment-banner"><div className="banner-icon"><FileText /></div><div><span className="eyebrow">Beyond the chapters</span><h3>Midterms and finals, when you are ready.</h3><p>Each course ends with an assessment that checks the whole picture, not just the last page.</p></div><button className="button button-outline" onClick={() => navigate('midterm')}>View assessments <ArrowRight size={15} /></button></div></>; }

function CourseDetail({ courseId, completed, results, onBack, onLearn, onNavigate }: { courseId: string; completed: string[]; results: { score: number; course_id: string; chapter_id: string; created_at: string }[]; onBack: () => void; onLearn: (id?: string) => void; onNavigate: (view: View) => void }): JSX.Element { const course = courses.find((item) => item.id === courseId) ?? courses[0]; const chapters = chapterSets[course.id]; const completedCount = chapters.filter((chapter) => completed.includes(chapter.id)).length; const progress = courseProgress(course.id, completed); const avgScore = courseAverageScore(results, course.id); return <><button className="back-link" onClick={onBack}><ArrowLeft size={15} /> All courses</button><div className={`course-hero course-hero-${course.tone}`}><div><span className="course-icon hero-icon">{course.icon}</span><span className="eyebrow light">{course.code} <i /> {course.level}</span><h1>{course.title}</h1><p>{course.description} This course uses a progressive outline with room for the real material to grow over time.</p><div className="hero-buttons"><button className="button button-light" onClick={() => onLearn(course.id)}>Continue course <ArrowRight size={16} /></button><button className="button button-ghost-light" onClick={() => onNavigate('midterm')}>View assessment</button></div></div><div className="course-hero-progress"><div className="ring-progress" style={{ '--progress': `${progress * 3.6}deg` } as React.CSSProperties}><div><strong>{progress}%</strong><span>complete</span></div></div><span>Overall course progress</span></div></div><div className="course-summary"><SummaryItem label="Chapters" value={String(chapters.length).padStart(2, '0')} /><SummaryItem label="Completed" value={`${completedCount} / ${chapters.length}`} /><SummaryItem label="Average test score" value={avgScore > 0 ? `${avgScore}%` : '—'} /><SummaryItem label="Tests taken" value={String(results.filter((r) => r.course_id === course.id).length).padStart(2, '0')} /></div><div className="chapter-section"><div className="section-bar"><div><span className="eyebrow">Course roadmap</span><h2>Follow the sequence.</h2></div><span className="muted-note"><CheckCircle2 size={15} /> {completedCount} completed</span></div><div className="chapter-list">{chapters.map((chapter) => { const isCompleted = completed.includes(chapter.id); const status = isCompleted ? 'completed' : chapter.status; return <ChapterCard key={chapter.id} chapter={{ ...chapter, status }} onOpen={() => status !== 'locked' && onLearn(course.id)} />; })}</div></div></>; }
function SummaryItem({ label, value }: { label: string; value: string }): JSX.Element { return <div><span>{label}</span><strong>{value}</strong></div>; }
function ChapterCard({ chapter, onOpen }: { chapter: Chapter; onOpen: () => void }): JSX.Element { const isLocked = chapter.status === 'locked'; return <div className={`chapter-card ${chapter.status}`}><div className="chapter-number">{chapter.status === 'completed' ? <Check size={16} /> : isLocked ? <LockKeyhole size={15} /> : chapter.number}</div><div className="chapter-content"><div className="chapter-heading"><div><span>Chapter {chapter.number}</span><h3>{chapter.title}</h3></div><StatusBadge status={chapter.status} /></div><p>{chapter.description}</p><div className="chapter-bottom"><span><Clock3 size={14} /> {chapter.duration}</span>{chapter.status !== 'locked' && <><ProgressBar value={chapter.progress} /><small>{chapter.progress}%</small></>}</div></div><button className={`chapter-action ${isLocked ? 'disabled' : ''}`} disabled={isLocked} onClick={onOpen}>{chapter.status === 'completed' ? 'Review' : chapter.status === 'in-progress' ? 'Continue' : isLocked ? 'Locked' : 'Start'} {!isLocked && <ChevronRight size={15} />}</button></div>; }
function StatusBadge({ status }: { status: Chapter['status'] }): JSX.Element { const labels = { completed: 'Completed', 'in-progress': 'In progress', available: 'Up next', locked: 'Locked' }; return <span className={`status-badge ${status}`}>{status === 'completed' && <Check size={12} />}{labels[status]}</span>; }

function InteractiveLearn({ courseId, chapterId, completed, onComplete, onNavigate, onSelectChapter }: { courseId: string; chapterId: string; completed: string[]; onComplete: () => void; onNavigate: (view: View) => void; onSelectChapter: (courseId: string, chapterId: string) => void }): JSX.Element {
  const course = courses.find((item) => item.id === courseId) ?? courses[0];
  const chapters = chapterSets[course.id] ?? [];
  const index = Math.max(0, chapters.findIndex((chapter) => chapter.id === chapterId));
  const chapter = chapters[index] ?? chapters[0];
  const [lesson, setLesson] = useState<ApiLesson | null>(null);
  useEffect(() => { let active = true; setLesson(null); api.material(chapter.id).then((content) => { if (active && content) setLesson(content); }).catch(() => undefined); return () => { active = false; }; }, [chapter.id]);
  const previous = chapters[index - 1];
  const next = chapters[index + 1];
  const isDone = completed.includes(chapter.id);
  if (!lesson) return <div className="lesson"><Loader2 size={24} className="spin" /></div>;
  return <div className="learn-layout"><aside className="learn-outline"><button className="back-link" onClick={() => navigate('course', course.id)}><ArrowLeft size={15} /> Back to course</button><div className="learn-course"><span className={`tiny-course-icon ${course.tone}`}>{course.icon}</span><div><b>{course.title}</b><small>{course.code}</small></div></div><div className="outline-title">In this course</div>{chapters.map((item) => <button key={item.id} className={item.id === chapter.id ? 'active' : ''} onClick={() => onSelectChapter(course.id, item.id)}><span>{item.number}</span>{item.title}{completed.includes(item.id) && <Check size={13} />}</button>)}<div className="learn-progress"><span>Course progress</span><b>{courseProgress(course.id, completed)}%</b><ProgressBar value={courseProgress(course.id, completed)} tone={course.tone} /></div></aside><article className="lesson"><div className="lesson-top"><span className="eyebrow">Chapter {lesson.chapterNumber} <i /> {course.title}</span><span className="lesson-time"><Clock3 size={14} /> {lesson.readTime}</span></div><h1>{lesson.title}</h1><p className="lesson-lead">{lesson.lead}</p><div className="lesson-callout"><span><Sparkles size={18} /></span><div><b>Learning objective</b><p>{lesson.objective}</p></div></div>{lesson.sections.map((section, sectionIndex) => <div key={sectionIndex}><h2>{section.heading}</h2><p>{section.body}</p>{section.code && <div className="code-block"><div className="code-block-header"><span>{section.code.file}</span><span>Example</span></div><pre><code>{section.code.lines}</code></pre></div>}</div>)}<h2>Three ideas to hold onto</h2><div className="concept-grid">{lesson.concepts.map((concept) => <Concept key={concept.number} number={concept.number} title={concept.title} text={concept.text} />)}</div><div className="lesson-note"><FileText size={18} /><div><b>Important note</b><p>{lesson.note}</p></div></div><div className="lesson-footer"><button className="button button-outline" disabled={!previous} onClick={() => previous && onSelectChapter(course.id, previous.id)}><ArrowLeft size={15} /> Previous</button><button className={`button ${isDone ? 'button-success' : 'button-primary'}`} onClick={onComplete}>{isDone ? <Check size={15} /> : <CheckCircle2 size={15} />} {isDone ? 'Completed' : 'Mark as complete'}</button><button className="button button-outline" disabled={!next} onClick={() => next && onSelectChapter(course.id, next.id)}>Next <ArrowRight size={15} /></button><button className="button button-outline" onClick={() => onNavigate('test')}>Take chapter test <FileCheck2 size={15} /></button></div></article></div>;
}

function Concept({ number, title, text }: { number: string; title: string; text: string }): JSX.Element { return <div className="concept"><span>{number}</span><h3>{title}</h3><p>{text}</p></div>; }

function Test({ courseId, chapterId, type, onSubmit, onNavigate }: { courseId: string; chapterId: string; type: AssessmentType; onSubmit: (result: Omit<Submission, 'type' | 'chapterId'>) => void; onNavigate: (view: View) => void }): JSX.Element {
  const fallbackQuiz: Quiz = type === 'chapter' ? quizzes[courseId] ?? quizzes.oop : examQuizzes[courseId]?.[type] ?? examQuizzes.oop[type];
  const [quiz, setQuiz] = useState<Quiz>(fallbackQuiz);
  useEffect(() => { let active = true; api.assessment(courseId, type, type === 'chapter' ? chapterId : undefined).then((assessment: ApiAssessment) => { if (!active) return; const localQuestions = fallbackQuiz.questions; setQuiz({ passingScore: 60, questions: assessment.questions.map((question, index) => ({ id: question.id, question: question.question, options: question.options, correctIndex: localQuestions[index]?.correctIndex ?? 0 })) }); }).catch(() => undefined); return () => { active = false; }; }, [courseId, chapterId, type]);
  const course = courses.find((c) => c.id === courseId) ?? courses[0];
  const total = quiz.questions.length;
  const [current, setCurrent] = useState(0);
  const [answers, setAnswers] = useState<(number | null)[]>(Array(total).fill(null));
  const [startTime] = useState(() => Date.now());
  const [submitting, setSubmitting] = useState(false);
  useEffect(() => { setAnswers(Array(total).fill(null)); setCurrent(0); }, [total]);

  const q = quiz.questions[current];
  const answeredCount = answers.filter((a) => a !== null).length;
  const progressPct = Math.round((answeredCount / total) * 100);
  const isLast = current === total - 1;

  const selectAnswer = (idx: number) => {
    setAnswers((prev) => { const next = [...prev]; next[current] = idx; return next; });
  };

  const goTo = (idx: number) => {
    if (idx >= 0 && idx < total) setCurrent(idx);
  };

  const finish = async () => {
    setSubmitting(true);
    let correct = 0;
    answers.forEach((a, i) => { if (a === quiz.questions[i].correctIndex) correct++; });
    const incorrect = total - correct;
    const score = Math.round((correct / total) * 100);
    const elapsed = Math.round((Date.now() - startTime) / 1000);
    const mins = Math.floor(elapsed / 60);
    const secs = elapsed % 60;
    const time = `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
    try {
      const saved = await api.submitAssessment(courseId, type, answers.map((answer) => answer ?? -1), time, type === 'chapter' ? chapterId : undefined);
      onSubmit({ score: saved.score, correct: saved.correct_answers, incorrect: saved.incorrect_answers, time: saved.time_taken, answers, questions: quiz.questions, resultId: Number(saved.id) });
    } catch {
      onSubmit({ score, correct, incorrect, time, answers, questions: quiz.questions });
    }
  };

  const title = type === 'chapter' ? 'Chapter test' : type === 'midterm' ? 'Midterm assessment' : 'Final examination';
  return <div className="test-page"><div className="test-header"><div><span className="eyebrow">{course.title} <i /> {title}</span><h1>{title}</h1><p>{type === 'chapter' ? 'Check your understanding before moving to the next quest.' : 'Work through the complete assessment, then submit when you are ready.'}</p></div><div className="test-meta"><span><FileCheck2 size={16} /> {total} questions</span><span><Clock3 size={16} /> Single choice</span></div></div>
  <div className="test-progress"><div><span>Question {String(current + 1).padStart(2, '0')} of {String(total).padStart(2, '0')}</span><b>{progressPct}% answered</b></div><ProgressBar value={progressPct} /></div>
  <div className="test-layout"><div className="question-card">
    <div className="question-kicker">Question {String(current + 1).padStart(2, '0')} <span>Single choice</span></div>
    <h2>{q.question}</h2>
    <div className="options">{q.options.map((option, idx) => <button key={option} className={answers[current] === idx ? 'selected' : ''} onClick={() => selectAnswer(idx)}><span className="radio">{answers[current] === idx && <i />}</span><span>{option}</span><kbd>{String.fromCharCode(65 + idx)}</kbd></button>)}</div>
    <div className="question-actions">
      <button className="button button-outline" onClick={() => onNavigate(type === 'chapter' ? 'learn' : type)}><ArrowLeft size={15} /> Exit test</button>
      <div style={{ display: 'flex', gap: 8 }}>
        {current > 0 && <button className="button button-outline" onClick={() => goTo(current - 1)}><ArrowLeft size={15} /> Prev</button>}
        {isLast
          ? <button className="button button-primary" onClick={finish} disabled={submitting || answeredCount !== total}>{submitting ? <Loader2 size={15} className="spin" /> : <CheckCircle2 size={15} />} Submit {type === 'chapter' ? 'test' : 'exam'}</button>
          : <button className="button button-primary" onClick={() => goTo(current + 1)} disabled={answers[current] === null}>Next <ArrowRight size={15} /></button>}
      </div>
    </div>
  </div>
  <div className="question-map"><span className="eyebrow">Question map</span><div>{quiz.questions.map((_, idx) => <button className={idx === current ? 'current' : answers[idx] !== null ? 'answered' : ''} key={idx} onClick={() => goTo(idx)}>{String(idx + 1).padStart(2, '0')}</button>)}</div>
    <div className="map-legend"><span><i className="current-dot" /> Current</span><span><i className="open-dot" /> Open</span><span><i className="answered-dot" /> Answered</span></div>
    <div className="test-tip"><Sparkles size={16} /><p>{answeredCount === total ? 'All answered. Ready to submit!' : `${total - answeredCount} question${total - answeredCount !== 1 ? 's' : ''} left.`}</p></div>
  </div></div>
  {submitting && <div className="toast"><CheckCircle2 size={17} /> Submitting your answers…</div>}</div>;
}

function Result({ courseId, onNavigate, score, onCourse }: { courseId: string; onNavigate: (view: View) => void; score: { score: number; correct: number; incorrect: number; time: string }; onCourse: (id: string) => void }): JSX.Element { const course = courses.find((item) => item.id === courseId) ?? courses[0]; const chapters = chapterSets[course.id]; const currentIdx = chapters.findIndex((ch) => ch.id === `${course.id}-3`); const nextCh = chapters[currentIdx + 1]; return <div className="result-page"><div className="result-heading"><span className="success-mark"><Check size={25} /></span><span className="eyebrow">Chapter test complete</span><h1>{score.score >= 80 ? 'Strong work.' : score.score >= 60 ? 'Good progress.' : 'Keep going.'}</h1><p>{score.score >= 80 ? 'You have a clear grasp of this chapter. Keep the momentum moving.' : score.score >= 60 ? 'You are on the right track. A little more practice and you will have it.' : 'Every attempt builds understanding. Review the material and try again.'}</p></div><div className="result-card"><div className="result-score"><div className="score-ring" style={{ background: `conic-gradient(var(--teal) ${score.score}%, #e6efeb 0)` }}><strong>{score.score}<span>%</span></strong><small>your score</small></div><div><span className="eyebrow">Performance summary</span><h2>{score.score >= 80 ? 'Above the course average' : score.score >= 60 ? 'On the right track' : 'Keep practicing'}</h2><p>Your answers show {score.score >= 80 ? 'a solid understanding' : 'you are building understanding'} of the core ideas.</p></div></div><div className="result-stats"><SummaryItem label="Correct answers" value={String(score.correct).padStart(2, '0')} /><SummaryItem label="Incorrect answers" value={String(score.incorrect).padStart(2, '0')} /><SummaryItem label="Time taken" value={score.time} /><SummaryItem label="Attempt" value="#01" /></div></div><div className="result-actions"><button className="button button-outline">Review test <FileText size={15} /></button><button className="button button-outline" onClick={() => onNavigate('course')}>Back to chapter <ArrowLeft size={15} /></button><button className="button button-primary" onClick={() => onNavigate('learn')}>Continue learning <ArrowRight size={15} /></button></div>{nextCh && <div className="next-up"><span className={`tiny-course-icon ${course.tone}`}><Zap size={16} /></span><div><span className="eyebrow">Next up in {course.title}</span><b>Chapter {nextCh.number} — {nextCh.title}</b></div><button className="inline-link" onClick={() => onCourse(course.id)}>Start now <ArrowRight size={15} /></button></div>}</div>; }

function Exam({ type, courseId, onNavigate }: { type: 'midterm' | 'final'; courseId: string; onNavigate: (view: View) => void }): JSX.Element { const course = courses.find((item) => item.id === courseId) ?? courses[0]; const isFinal = type === 'final'; const questionCount = examQuizzes[course.id][type].questions.length; return <div className="exam-page"><button className="back-link" onClick={() => onNavigate('course')}><ArrowLeft size={15} /> Back to {course.title}</button><div className={`exam-hero ${isFinal ? 'final' : ''}`}><span className="exam-icon">{isFinal ? <GraduationCap /> : <ShieldCheck />}</span><span className="eyebrow light">{course.title} <i /> Assessment</span><h1>{isFinal ? 'Final examination' : 'Midterm assessment'}</h1><p>{isFinal ? 'Bring the full course picture together and show what you can do.' : 'A focused checkpoint across the first half of your course journey.'}</p></div><div className="exam-body"><div className="exam-info"><div><span className="eyebrow">Coverage</span><h2>{isFinal ? 'All course chapters' : 'Chapters 01 — 06'}</h2><p>{isFinal ? 'The complete outline, with emphasis on applying concepts rather than recalling isolated terms.' : 'Foundations, core concepts, and the patterns you have practiced so far.'}</p></div><div className="exam-facts"><SummaryItem label="Questions" value={String(questionCount)} /><SummaryItem label="Time limit" value={isFinal ? '60 min' : '40 min'} /><SummaryItem label="Attempts" value="01" /></div></div><div className="instructions"><span className="eyebrow">Before you begin</span>{['Make sure you have a quiet space and a stable connection.', 'You can move between questions before submitting.', 'Your result will be available immediately after submission.'].map((item) => <div key={item}><CheckCircle2 size={16} /><span>{item}</span></div>)}</div><button className="button button-primary exam-start" onClick={() => navigate('test', `${courseId}/${type}`)}>Start {isFinal ? 'final exam' : 'midterm'} <ArrowRight size={16} /></button></div></div>; }

function Progress({ completions, results }: { completions: string[]; results: { score: number; course_id: string; chapter_id: string; created_at: string }[] }): JSX.Element { const overall = overallProgress(completions); const avg = averageScore(results); return <><PageTitle eyebrow="Your progress" title="See the bigger picture." text="Progress is not a grade. It is a map of where your next hour matters most." action={<button className="button button-outline"><FileText size={15} /> Export report</button>} /><div className="progress-overview"><div className="overall-ring" style={{ background: `conic-gradient(var(--teal) ${overall}%, #d4e8e0 0)` }}><div><strong>{overall}%</strong><span>overall</span></div></div><div><span className="eyebrow">Across all courses</span><h2>{overall > 0 ? 'You are building real momentum.' : 'Your journey starts here.'}</h2><p>{completions.length} chapters completed, {results.length} tests attempted, and {avg > 0 ? `a ${avg}% average score` : 'no test scores yet'} to build on.</p><div className="progress-highlights"><SummaryItem label="Chapters completed" value={String(completions.length).padStart(2, '0')} /><SummaryItem label="Tests attempted" value={String(results.length).padStart(2, '0')} /><SummaryItem label="Average score" value={`${avg}%`} /></div></div></div><div className="progress-columns"><div className="progress-course-panel"><div className="section-bar"><div><span className="eyebrow">Course breakdown</span><h2>One path at a time.</h2></div></div>{courses.map((course) => { const p = courseProgress(course.id, completions); const done = (chapterSets[course.id] ?? []).filter((ch) => completions.includes(ch.id)).length; return <div className="breakdown-row" key={course.id}><div className="breakdown-title"><span className={`tiny-course-icon ${course.tone}`}>{course.icon}</span><div><b>{course.title}</b><small>{p}% complete</small></div><strong>{p}%</strong></div><ProgressBar value={p} tone={course.tone} /><div className="breakdown-footer"><span>{done} of {chapterSets[course.id]?.length ?? course.chapters} chapters</span><span>{p > 50 ? 'On track' : p > 0 ? 'Keep going' : 'Not started'}</span></div></div>; })}</div><div className="score-panel"><div className="section-bar"><div><span className="eyebrow">Assessment scores</span><h2>Learning signals</h2></div></div><ScoreRow label="Chapter tests" value={`${avg}%`} progress={avg} /><ScoreRow label="Midterm assessment" value="—" progress={0} /><ScoreRow label="Final examination" value="—" progress={0} /><div className="progress-tip"><Trophy size={17} /><span><b>Best streak: 7 days</b><small>Keep your learning rhythm steady.</small></span></div></div></div></>; }
function ScoreRow({ label, value, progress }: { label: string; value: string; progress: number }): JSX.Element { return <div className="score-row"><div><span>{label}</span><b>{value}</b></div><ProgressBar value={progress} tone="cyan" /></div>; }

function ProgressReport({ completions, results, userName }: { completions: string[]; results: { score: number; course_id: string; chapter_id: string; created_at: string }[]; userName: string }): JSX.Element {
  const overall = overallProgress(completions);
  const average = averageScore(results);
  const exportReport = (): void => {
    const rows = [['Code Quest progress report'], ['Student', userName], ['Overall progress', `${overall}%`], [''], ['Course', 'Completed chapters', 'Progress'], ...courses.map((course) => [course.title, `${(chapterSets[course.id] ?? []).filter((chapter) => completions.includes(chapter.id)).length}/${chapterSets[course.id]?.length ?? 0}`, `${courseProgress(course.id, completions)}%`]), [''], ['Assessment', 'Course', 'Score', 'Date'], ...results.map((result) => [result.chapter_id.includes('midterm') ? 'Midterm' : result.chapter_id.includes('final') ? 'Final' : 'Chapter test', result.course_id.toUpperCase(), `${result.score}%`, new Date(result.created_at).toLocaleDateString()])];
    const csv = rows.map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(',')).join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); const link = document.createElement('a'); link.href = url; link.download = 'code-quest-progress.csv'; link.click(); URL.revokeObjectURL(url);
  };
  const midterm = results.filter((result) => result.chapter_id.includes('midterm')).sort((a, b) => b.score - a.score)[0];
  const final = results.filter((result) => result.chapter_id.includes('final')).sort((a, b) => b.score - a.score)[0];
  return <><PageTitle eyebrow="Your progress" title="See the bigger picture." text="Progress is not a grade. It is a map of where your next hour matters most." action={<button className="button button-outline" onClick={exportReport}><FileText size={15} /> Export report</button>} /><div className="progress-overview"><div className="overall-ring" style={{ background: `conic-gradient(var(--teal) ${overall}%, #d4e8e0 0)` }}><div><strong>{overall}%</strong><span>overall</span></div></div><div><span className="eyebrow">Across all courses</span><h2>{overall > 0 ? 'You are building real momentum.' : 'Your journey starts here.'}</h2><p>{completions.length} chapters completed, {results.length} tests attempted, and {average > 0 ? `a ${average}% average score` : 'no test scores yet'} to build on.</p><div className="progress-highlights"><SummaryItem label="Chapters completed" value={String(completions.length).padStart(2, '0')} /><SummaryItem label="Tests attempted" value={String(results.length).padStart(2, '0')} /><SummaryItem label="Average score" value={`${average}%`} /></div></div></div><div className="progress-columns"><div className="progress-course-panel"><div className="section-bar"><div><span className="eyebrow">Course breakdown</span><h2>One path at a time.</h2></div></div>{courses.map((course) => { const progress = courseProgress(course.id, completions); const done = (chapterSets[course.id] ?? []).filter((chapter) => completions.includes(chapter.id)).length; return <div className="breakdown-row" key={course.id}><div className="breakdown-title"><span className={`tiny-course-icon ${course.tone}`}>{course.icon}</span><div><b>{course.title}</b><small>{progress}% complete</small></div><strong>{progress}%</strong></div><ProgressBar value={progress} tone={course.tone} /><div className="breakdown-footer"><span>{done} of {chapterSets[course.id]?.length ?? course.chapters} chapters</span><span>{progress > 50 ? 'On track' : progress > 0 ? 'Keep going' : 'Not started'}</span></div></div>; })}</div><div className="score-panel"><div className="section-bar"><div><span className="eyebrow">Assessment scores</span><h2>Learning signals</h2></div></div><ScoreRow label="Chapter tests" value={`${average}%`} progress={average} /><ScoreRow label="Midterm assessment" value={midterm ? `${midterm.score}%` : '—'} progress={midterm?.score ?? 0} /><ScoreRow label="Final examination" value={final ? `${final.score}%` : '—'} progress={final?.score ?? 0} /><div className="progress-tip"><Trophy size={17} /><span><b>Keep your learning rhythm steady.</b><small>{userName}, every completed chapter adds to the map.</small></span></div></div></div></>;
}

function ResultReview({ courseId, resultId, onNavigate, score, onCourse }: { courseId: string; resultId: number | null; onNavigate: (view: View) => void; score: { score: number; correct: number; incorrect: number; time: string }; onCourse: (id: string) => void }): JSX.Element {
  const course = courses.find((item) => item.id === courseId) ?? courses[0]; const [persisted, setPersisted] = useState<Submission | null>(latestSubmission); const submission = persisted; const [reviewing, setReviewing] = useState(false); const next = chapterSets[course.id][2];
  useEffect(() => { if (!resultId) return; api.result(resultId).then((result) => { setPersisted({ score: result.score, correct: result.correct_answers, incorrect: result.incorrect_answers, time: result.time_taken, type: result.assessment_type, chapterId: result.chapter_id, answers: result.review_data.answers, questions: result.review_data.questions.map((question) => ({ ...question, correctIndex: question.correctIndex })) as Question[], resultId }); }).catch(() => undefined); }, [resultId]);
  return <div className="result-page"><div className="result-heading"><span className="success-mark"><Check size={25} /></span><span className="eyebrow">{submission?.type === 'chapter' ? 'Chapter test' : submission?.type === 'midterm' ? 'Midterm' : 'Final'} complete</span><h1>{score.score >= 80 ? 'Strong work.' : score.score >= 60 ? 'Good progress.' : 'Keep going.'}</h1><p>Your score is {score.score}%. Review the answers below or continue learning.</p></div><div className="result-card"><div className="result-score"><div className="score-ring" style={{ background: `conic-gradient(var(--teal) ${score.score}%, #e6efeb 0)` }}><strong>{score.score}<span>%</span></strong><small>your score</small></div><div><span className="eyebrow">Performance summary</span><h2>{score.correct} correct answers</h2><p>{score.incorrect} incorrect answers · {score.time} taken</p></div></div><div className="result-stats"><SummaryItem label="Correct answers" value={String(score.correct).padStart(2, '0')} /><SummaryItem label="Incorrect answers" value={String(score.incorrect).padStart(2, '0')} /><SummaryItem label="Time taken" value={score.time} /><SummaryItem label="Questions" value={String(submission?.questions.length ?? score.correct + score.incorrect)} /></div></div>{reviewing && submission && <div className="review-list">{submission.questions.map((question, index) => { const answer = submission.answers[index]; const correct = answer === question.correctIndex; return <div className="review-item" key={question.id}><span className="eyebrow">Question {String(index + 1).padStart(2, '0')} · {correct ? 'Correct' : 'Incorrect'}</span><h3>{question.question}</h3><p>Your answer: <b>{answer === null ? 'No answer' : question.options[answer]}</b></p><p>Correct answer: <b>{question.options[question.correctIndex]}</b></p></div>; })}</div>}<div className="result-actions"><button className="button button-outline" onClick={() => setReviewing((value) => !value)}><FileText size={15} /> {reviewing ? 'Hide review' : 'Review test'}</button><button className="button button-outline" onClick={() => onNavigate('course')}><ArrowLeft size={15} /> Back to chapter</button><button className="button button-primary" onClick={() => onCourse(course.id)}>Continue learning <ArrowRight size={15} /></button></div><div className="next-up"><span className={`tiny-course-icon ${course.tone}`}><Zap size={16} /></span><div><span className="eyebrow">Next up in {course.title}</span><b>Chapter {next.number} — {next.title}</b></div><button className="inline-link" onClick={() => onCourse(course.id)}>Start now <ArrowRight size={15} /></button></div></div>;
}
function Profile({ profile, email }: { profile: { full_name: string; learning_goal: string } | null; email: string }): JSX.Element { const name = profile?.full_name || email.split('@')[0] || 'Student'; const userInitials = initials(name); return <><PageTitle eyebrow="Your profile" title={name} text="Keep your learning identity and goals close." action={<button className="button button-outline"><Settings size={15} /> Account settings</button>} /><div className="profile-grid"><section className="profile-card"><div className="profile-cover" /><div className="profile-avatar">{userInitials}</div><div className="profile-details"><div className="profile-detail-heading"><div><h2>{name}</h2><p>Computer Science · Undergraduate</p></div><button className="button button-outline small">Edit profile</button></div><div className="detail-lines"><div><span>Email</span><b>{email}</b></div><div><span>Member since</span><b>October 2026</b></div><div><span>Learning goal</span><b>{profile?.learning_goal || 'Build confident fundamentals'}</b></div></div></div></section><aside className="profile-side"><div className="section-bar"><div><span className="eyebrow">Achievements</span><h2>Quiet wins.</h2></div></div><div className="achievement-list"><div><span className="achievement-icon cyan"><CheckCircle2 /></span><div><b>First quest</b><small>Completed your first chapter</small></div></div><div><span className="achievement-icon amber"><Zap /></span><div><b>Momentum</b><small>Maintained a 7-day streak</small></div></div><div><span className="achievement-icon emerald"><Target /></span><div><b>Test ready</b><small>Scored above 80% three times</small></div></div></div></aside></div></>; }
function ProfileEditor({ profile, email }: { profile: { full_name: string; learning_goal: string } | null; email: string }): JSX.Element {
  const { updateProfile } = useAuth();
  const [name, setName] = useState(profile?.full_name || email.split('@')[0] || 'Student');
  const [goal, setGoal] = useState(profile?.learning_goal || 'Build confident fundamentals');
  const [editing, setEditing] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const save = async (): Promise<void> => { const { error } = await updateProfile(name.trim(), goal.trim()); setMessage(error ?? 'Profile saved.'); if (!error) setEditing(false); };
  const userInitials = initials(name);
  return <><PageTitle eyebrow="Your profile" title={name} text="Keep your learning identity and goals close." action={<button className="button button-outline" onClick={() => setEditing(true)}><Settings size={15} /> Account settings</button>} /><div className="profile-grid"><section className="profile-card"><div className="profile-cover" /><div className="profile-avatar">{userInitials}</div><div className="profile-details"><div className="profile-detail-heading"><div><h2>{name}</h2><p>Computer Science · Undergraduate</p></div><button className="button button-outline small" onClick={() => setEditing((value) => !value)}>{editing ? 'Close' : 'Edit profile'}</button></div>{editing ? <div className="profile-form"><label>Name<input value={name} onChange={(event) => setName(event.target.value)} /></label><label>Learning goal<input value={goal} onChange={(event) => setGoal(event.target.value)} /></label><button className="button button-primary" onClick={save}>Save changes <Check size={15} /></button>{message && <span className="profile-message">{message}</span>}</div> : <div className="detail-lines"><div><span>Email</span><b>{email}</b></div><div><span>Member since</span><b>October 2026</b></div><div><span>Learning goal</span><b>{goal}</b></div></div>}</div></section><aside className="profile-side"><div className="section-bar"><div><span className="eyebrow">Achievements</span><h2>Quiet wins.</h2></div></div><div className="achievement-list"><div><span className="achievement-icon cyan"><CheckCircle2 /></span><div><b>First quest</b><small>Completed your first chapter</small></div></div><div><span className="achievement-icon amber"><Zap /></span><div><b>Momentum</b><small>Maintained a 7-day streak</small></div></div><div><span className="achievement-icon emerald"><Target /></span><div><b>Test ready</b><small>Scored above 80% three times</small></div></div></div></aside></div></>;
}

function Admin(): JSX.Element {
  const { user } = useAuth();
  const [testId, setTestId] = useState(''); const [question, setQuestion] = useState(''); const [options, setOptions] = useState(''); const [correctIndex, setCorrectIndex] = useState('0');
  const [examId, setExamId] = useState(''); const [message, setMessage] = useState<string | null>(null);
  if (user?.role !== 'admin') return <PageTitle eyebrow="Restricted" title="Admin access required." text="Sign in with an administrator account to manage Code Quest content." />;
  const createQuestion = async (): Promise<void> => { try { await api.adminCreateQuestion({ test_id: Number(testId), question, options: options.split('|').map((item) => item.trim()).filter(Boolean), correct_index: Number(correctIndex) }); setMessage('Question created.'); setQuestion(''); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not create question.'); } };
  const createExamQuestion = async (): Promise<void> => { try { await api.adminCreateExamQuestion({ exam_id: Number(examId), question, options: options.split('|').map((item) => item.trim()).filter(Boolean), correct_index: Number(correctIndex) }); setMessage('Exam question created.'); setQuestion(''); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not create exam question.'); } };
  return <><PageTitle eyebrow="Administration" title="Manage assessments." text="Add questions to the seeded tests and exams without changing the student experience." /><div className="profile-grid"><section className="profile-card"><div className="profile-details"><div className="eyebrow">Chapter test question</div><div className="profile-form"><label>Test ID<input value={testId} onChange={(event) => setTestId(event.target.value)} placeholder="1" /></label><label>Question<input value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Question text" /></label><label>Options<input value={options} onChange={(event) => setOptions(event.target.value)} placeholder="Option A | Option B | Option C | Option D" /></label><label>Correct option index<input type="number" min="0" value={correctIndex} onChange={(event) => setCorrectIndex(event.target.value)} /></label><button className="button button-primary" onClick={createQuestion}>Create test question</button></div></div></section><section className="profile-card"><div className="profile-details"><div className="eyebrow">Midterm / final question</div><div className="profile-form"><label>Exam ID<input value={examId} onChange={(event) => setExamId(event.target.value)} placeholder="1" /></label><label>Question<input value={question} onChange={(event) => setQuestion(event.target.value)} placeholder="Question text" /></label><label>Options<input value={options} onChange={(event) => setOptions(event.target.value)} placeholder="Option A | Option B | Option C | Option D" /></label><label>Correct option index<input type="number" min="0" value={correctIndex} onChange={(event) => setCorrectIndex(event.target.value)} /></label><button className="button button-primary" onClick={createExamQuestion}>Create exam question</button>{message && <span className="profile-message">{message}</span>}</div></div></section></div></>;
}

function AdminPanel(): JSX.Element {
  const { user } = useAuth();
  type AdminCourse = { id: number; slug: string; title: string; code: string | null; description: string | null; level: string | null };
  type AdminChapter = { id: number; course_id: number; slug: string; number: number; title: string; description: string | null; status: string; duration: string | null };
  type AdminMaterial = { id: number; chapter_id: number; title: string; content: unknown };
  type AdminTest = { id: number; course_id: number; chapter_id: number | null; type: string; title: string };
  type AdminExam = { id: number; course_id: number; type: string; title: string };
  type TestQuestion = { id: number; test_id: number; question: string; options: { id: number; option: string; is_correct: boolean }[] };
  type ExamQuestion = { id: number; exam_id: number; question: string; options: string[]; correct_index: number };
  const [courses, setCourses] = useState<AdminCourse[]>([]); const [chapters, setChapters] = useState<AdminChapter[]>([]); const [materials, setMaterials] = useState<AdminMaterial[]>([]); const [tests, setTests] = useState<AdminTest[]>([]); const [exams, setExams] = useState<AdminExam[]>([]); const [testQuestions, setTestQuestions] = useState<TestQuestion[]>([]); const [examQuestions, setExamQuestions] = useState<ExamQuestion[]>([]); const [message, setMessage] = useState<string | null>(null);
  const [courseId, setCourseId] = useState(''); const [chapterId, setChapterId] = useState(''); const [testId, setTestId] = useState(''); const [examId, setExamId] = useState('');
  const [courseForm, setCourseForm] = useState({ slug: '', title: '', code: '', level: '', description: '' }); const [chapterForm, setChapterForm] = useState({ course_id: '', number: '', slug: '', title: '', description: '', status: 'available', duration: '' }); const [materialForm, setMaterialForm] = useState({ chapter_id: '', title: '', content: '{\n  "sections": []\n}' });
  const [testQuestionForm, setTestQuestionForm] = useState({ question: '', options: '', correct_index: '0' }); const [examQuestionForm, setExamQuestionForm] = useState({ question: '', options: '', correct_index: '0' });
  const load = async (): Promise<void> => { try { const [courseData, chapterData, materialData, testData, examData, questionData, examQuestionData] = await Promise.all([api.adminCourses(), api.adminChapters(), api.adminMaterials(), api.adminTests(), api.adminExams(), api.adminQuestions(), api.adminExamQuestions()]); setCourses(courseData.courses as AdminCourse[]); setChapters(chapterData.chapters as AdminChapter[]); setMaterials(materialData.materials as AdminMaterial[]); setTests(testData.tests as AdminTest[]); setExams(examData.exams as AdminExam[]); setTestQuestions(questionData.questions as TestQuestion[]); setExamQuestions(examQuestionData.questions as ExamQuestion[]); setMessage(null); } catch (error) { setMessage(error instanceof Error ? error.message : 'Could not load admin data.'); } };
  useEffect(() => { if (user?.role === 'admin') void load(); }, [user?.role]);
  if (user?.role !== 'admin') return <PageTitle eyebrow="Restricted" title="Admin access required." text="Sign in with an administrator account to manage Code Quest content." />;
  const run = async (action: () => Promise<unknown>): Promise<void> => { try { await action(); await load(); } catch (error) { setMessage(error instanceof Error ? error.message : 'The change could not be saved.'); } };
  const editCourse = async (course: AdminCourse): Promise<void> => { const title = window.prompt('Course title', course.title); if (title === null) return; const slug = window.prompt('Course slug', course.slug); if (slug === null) return; await run(() => api.adminUpdateCourse(course.id, { title, slug, code: window.prompt('Course code', course.code ?? '') ?? course.code, level: window.prompt('Level', course.level ?? '') ?? course.level, description: window.prompt('Description', course.description ?? '') ?? course.description })); };
  const editChapter = async (chapter: AdminChapter): Promise<void> => { const title = window.prompt('Chapter title', chapter.title); if (title === null) return; const slug = window.prompt('Chapter slug', chapter.slug); if (slug === null) return; const number = window.prompt('Chapter number', String(chapter.number)); if (number === null) return; await run(() => api.adminUpdateChapter(chapter.id, { title, slug, number: Number(number), course_id: chapter.course_id, status: chapter.status, description: window.prompt('Description', chapter.description ?? '') ?? chapter.description, duration: window.prompt('Duration', chapter.duration ?? '') ?? chapter.duration })); };
  const editMaterial = async (material: AdminMaterial): Promise<void> => { const title = window.prompt('Material title', material.title); if (title === null) return; const content = window.prompt('Material content (JSON)', JSON.stringify(material.content, null, 2)); if (content === null) return; try { await run(() => api.adminUpdateMaterial(material.id, { title, content: JSON.parse(content) })); } catch { setMessage('Content must be valid JSON.'); } };
  const editTestQuestion = async (item: TestQuestion): Promise<void> => { const question = window.prompt('Question', item.question); if (question === null) return; const options = window.prompt('Options, one per line', item.options.map((option) => option.option).join('\n')); if (options === null) return; const rows = options.split('\n').map((option) => option.trim()).filter(Boolean); const correct = window.prompt('Correct option number (starting at 1)', String(item.options.findIndex((option) => option.is_correct) + 1)); if (correct === null) return; await run(() => api.adminUpdateQuestion(item.id, { question, options: rows, correct_index: Number(correct) - 1 })); };
  const editExamQuestion = async (item: ExamQuestion): Promise<void> => { const question = window.prompt('Question', item.question); if (question === null) return; const options = window.prompt('Options, one per line', item.options.join('\n')); if (options === null) return; const rows = options.split('\n').map((option) => option.trim()).filter(Boolean); const correct = window.prompt('Correct option number (starting at 1)', String(item.correct_index + 1)); if (correct === null) return; await run(() => api.adminUpdateExamQuestion(item.id, { question, options: rows, correct_index: Number(correct) - 1 })); };
  const createTestQuestion = async (): Promise<void> => { await run(async () => { await api.adminCreateQuestion({ test_id: Number(testId), question: testQuestionForm.question, options: testQuestionForm.options.split('\n').map((value) => value.trim()).filter(Boolean), correct_index: Number(testQuestionForm.correct_index) }); setTestQuestionForm({ question: '', options: '', correct_index: '0' }); }); };
  const createExamQuestion = async (): Promise<void> => { await run(async () => { await api.adminCreateExamQuestion({ exam_id: Number(examId), question: examQuestionForm.question, options: examQuestionForm.options.split('\n').map((value) => value.trim()).filter(Boolean), correct_index: Number(examQuestionForm.correct_index) }); setExamQuestionForm({ question: '', options: '', correct_index: '0' }); }); };
  return <><PageTitle eyebrow="Administration" title="Manage Code Quest." text="Create and maintain course content and assessment questions." action={<button className="button button-outline" onClick={() => void load()}>Refresh data</button>} />{message && <div className="profile-message" role="status">{message}</div>}
    <div className="profile-grid admin-grid">
      <section className="profile-card"><div className="profile-details"><span className="eyebrow">Courses · {courses.length}</span><form className="profile-form" onSubmit={(event) => { event.preventDefault(); void run(async () => { await api.adminCreateCourse(courseForm); setCourseForm({ slug: '', title: '', code: '', level: '', description: '' }); }); }}><label>Title<input required value={courseForm.title} onChange={(event) => setCourseForm({ ...courseForm, title: event.target.value })} /></label><label>Slug<input required value={courseForm.slug} onChange={(event) => setCourseForm({ ...courseForm, slug: event.target.value })} /></label><label>Code<input value={courseForm.code} onChange={(event) => setCourseForm({ ...courseForm, code: event.target.value })} /></label><label>Level<input value={courseForm.level} onChange={(event) => setCourseForm({ ...courseForm, level: event.target.value })} /></label><label>Description<input value={courseForm.description} onChange={(event) => setCourseForm({ ...courseForm, description: event.target.value })} /></label><button className="button button-primary">Create course</button></form>{courses.map((item) => <div className="admin-row" key={item.id}><span><b>{item.title}</b><small>{item.slug}</small></span><button className="inline-link" onClick={() => void editCourse(item)}>Edit</button><button className="inline-link" onClick={() => window.confirm('Delete this course and its content?') && void run(() => api.adminDeleteCourse(item.id))}>Delete</button></div>)}</div></section>
      <section className="profile-card"><div className="profile-details"><span className="eyebrow">Chapters · {chapters.length}</span><form className="profile-form" onSubmit={(event) => { event.preventDefault(); void run(async () => { await api.adminCreateChapter({ ...chapterForm, course_id: Number(chapterForm.course_id), number: Number(chapterForm.number) }); setChapterForm({ course_id: '', number: '', slug: '', title: '', description: '', status: 'available', duration: '' }); }); }}><label>Course<select required value={chapterForm.course_id} onChange={(event) => setChapterForm({ ...chapterForm, course_id: event.target.value })}><option value="">Choose course</option>{courses.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label>Number<input required type="number" min="1" value={chapterForm.number} onChange={(event) => setChapterForm({ ...chapterForm, number: event.target.value, slug: chapterForm.slug || `chapter-${event.target.value}` })} /></label><label>Slug<input required value={chapterForm.slug} onChange={(event) => setChapterForm({ ...chapterForm, slug: event.target.value })} /></label><label>Title<input required value={chapterForm.title} onChange={(event) => setChapterForm({ ...chapterForm, title: event.target.value })} /></label><label>Description<input value={chapterForm.description} onChange={(event) => setChapterForm({ ...chapterForm, description: event.target.value })} /></label><button className="button button-primary">Create chapter</button></form>{chapters.map((item) => <div className="admin-row" key={item.id}><span><b>{item.number}. {item.title}</b><small>{courses.find((course) => course.id === item.course_id)?.title ?? `Course ${item.course_id}`}</small></span><button className="inline-link" onClick={() => void editChapter(item)}>Edit</button><button className="inline-link" onClick={() => window.confirm('Delete this chapter and its content?') && void run(() => api.adminDeleteChapter(item.id))}>Delete</button></div>)}</div></section>
    </div>
    <div className="profile-grid admin-grid">
      <section className="profile-card"><div className="profile-details"><span className="eyebrow">Learning materials · {materials.length}</span><form className="profile-form" onSubmit={(event) => { event.preventDefault(); void run(async () => { await api.adminCreateMaterial({ chapter_id: Number(materialForm.chapter_id), title: materialForm.title, content: JSON.parse(materialForm.content) }); setMaterialForm({ chapter_id: '', title: '', content: '{\n  "sections": []\n}' }); }); }}><label>Chapter<select required value={materialForm.chapter_id} onChange={(event) => setMaterialForm({ ...materialForm, chapter_id: event.target.value })}><option value="">Choose chapter</option>{chapters.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label>Title<input required value={materialForm.title} onChange={(event) => setMaterialForm({ ...materialForm, title: event.target.value })} /></label><label>Content (JSON)<textarea required rows={5} value={materialForm.content} onChange={(event) => setMaterialForm({ ...materialForm, content: event.target.value })} /></label><button className="button button-primary">Create material</button></form>{materials.map((item) => <div className="admin-row" key={item.id}><span><b>{item.title}</b><small>{chapters.find((chapter) => chapter.id === item.chapter_id)?.title ?? `Chapter ${item.chapter_id}`}</small></span><button className="inline-link" onClick={() => void editMaterial(item)}>Edit</button><button className="inline-link" onClick={() => window.confirm('Delete this material?') && void run(() => api.adminDeleteMaterial(item.id))}>Delete</button></div>)}</div></section>
      <section className="profile-card"><div className="profile-details"><span className="eyebrow">Chapter test questions · {testQuestions.length}</span><form className="profile-form" onSubmit={(event) => { event.preventDefault(); void createTestQuestion(); }}><label>Test<select required value={testId} onChange={(event) => setTestId(event.target.value)}><option value="">Choose chapter test</option>{tests.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></label><label>Question<textarea required rows={2} value={testQuestionForm.question} onChange={(event) => setTestQuestionForm({ ...testQuestionForm, question: event.target.value })} /></label><label>Options (one per line)<textarea required rows={4} value={testQuestionForm.options} onChange={(event) => setTestQuestionForm({ ...testQuestionForm, options: event.target.value })} /></label><label>Correct option number<input required type="number" min="1" value={Number(testQuestionForm.correct_index) + 1} onChange={(event) => setTestQuestionForm({ ...testQuestionForm, correct_index: String(Number(event.target.value) - 1) })} /></label><button className="button button-primary">Create test question</button></form>{testQuestions.map((item) => <div className="admin-row" key={item.id}><span><b>{item.question}</b><small>Test {item.test_id} · {item.options.length} options</small></span><button className="inline-link" onClick={() => void editTestQuestion(item)}>Edit</button><button className="inline-link" onClick={() => window.confirm('Delete this question?') && void run(() => api.adminDeleteQuestion(item.id))}>Delete</button></div>)}</div></section>
    </div>
    <section className="profile-card admin-exams"><div className="profile-details"><span className="eyebrow">Midterm and final questions · {examQuestions.length}</span><form className="profile-form admin-question-form" onSubmit={(event) => { event.preventDefault(); void createExamQuestion(); }}><label>Assessment<select required value={examId} onChange={(event) => setExamId(event.target.value)}><option value="">Choose midterm or final</option>{exams.map((item) => <option key={item.id} value={item.id}>{item.title} · {item.type}</option>)}</select></label><label>Question<textarea required rows={2} value={examQuestionForm.question} onChange={(event) => setExamQuestionForm({ ...examQuestionForm, question: event.target.value })} /></label><label>Options (one per line)<textarea required rows={4} value={examQuestionForm.options} onChange={(event) => setExamQuestionForm({ ...examQuestionForm, options: event.target.value })} /></label><label>Correct option number<input required type="number" min="1" value={Number(examQuestionForm.correct_index) + 1} onChange={(event) => setExamQuestionForm({ ...examQuestionForm, correct_index: String(Number(event.target.value) - 1) })} /></label><button className="button button-primary">Create exam question</button></form>{examQuestions.map((item) => <div className="admin-row" key={item.id}><span><b>{item.question}</b><small>Assessment {item.exam_id} · {item.options.length} options · correct: {item.options[item.correct_index]}</small></span><button className="inline-link" onClick={() => void editExamQuestion(item)}>Edit</button><button className="inline-link" onClick={() => window.confirm('Delete this question?') && void run(() => api.adminDeleteExamQuestion(item.id))}>Delete</button></div>)}</div></section>
  </>;
}

function Auth({ mode, onNavigate }: { mode: View; onNavigate: (view: View) => void }): JSX.Element {
  const { signIn, signUp } = useAuth();
  const isLogin = mode === 'login';
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async () => {
    setError(null);
    setSubmitting(true);
    if (isLogin) {
      const { error } = await signIn(email, password);
      if (error) { setError(error); setSubmitting(false); return; }
      navigate('dashboard');
    } else {
      const { error } = await signUp(email, password, fullName);
      if (error) { setError(error); setSubmitting(false); return; }
      navigate('dashboard');
    }
  };

  return <div className="auth-page"><div className="auth-brand"><Logo /><div className="auth-quote"><span className="eyebrow light">Built for the curious</span><h1>Every hard concept has a path through it.</h1><p>Code Quest gives you the structure to keep going when the material gets complex.</p><div className="quote-line"><span className="avatar">AM</span><span>“The best progress is the kind you can see.”</span></div></div><div className="auth-foot">© 2026 Code Quest <span>•</span> Learn with intent.</div></div><div className="auth-form-wrap"><button className="back-link" onClick={() => onNavigate('home')}><ArrowLeft size={15} /> Back to home</button><div className="auth-form"><span className="eyebrow">{isLogin ? 'Welcome back' : 'Start your journey'}</span><h2>{isLogin ? 'Log in to your quest' : 'Create your account'}</h2><p>{isLogin ? 'Pick up exactly where you left off.' : 'Your focused CS learning space is one step away.'}</p>{!isLogin && <label>Full name<input value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="Amina Malik" /></label>}<label>Email address<input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@university.edu" /></label><label>Password<input type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" /></label>{!isLogin && <label>Confirm password<input type="password" placeholder="Repeat your password" /></label>}{error && <div className="auth-error" role="alert">{error}</div>}{isLogin && <div className="form-options"><label className="checkbox"><input type="checkbox" /> Remember me</label><button>Forgot password?</button></div>}<button className="button button-primary auth-submit" onClick={handleSubmit} disabled={submitting || !email || !password}>{submitting ? <Loader2 size={16} className="spin" /> : isLogin ? <><LogIn size={16} /> Log in</> : <>Create account <ArrowRight size={16} /></>}</button><div className="auth-switch">{isLogin ? 'New to Code Quest?' : 'Already have an account?'} <button onClick={() => onNavigate(isLogin ? 'register' : 'login')}>{isLogin ? 'Create an account' : 'Log in'}</button></div></div></div></div>;
}
function Footer(): JSX.Element { return <footer id="about" className="footer"><div className="page-width footer-grid"><div><Logo /><p>A focused learning platform for the next generation of computer scientists.</p></div><div><b>Explore</b><a href="#courses">Courses</a><a href="#how">How it works</a><a href="#features">Features</a></div><div><b>Learn</b><button onClick={() => navigate('login')}>Log in</button><button onClick={() => navigate('register')}>Create account</button><button onClick={() => navigate('profile')}>Your profile</button></div><div><b>Need help?</b><p>Questions about your learning path?</p><a href="mailto:hello@codequest.edu">hello@codequest.edu</a></div></div><div className="page-width footer-bottom"><span>© 2026 Code Quest. Built for better learning.</span><span>Learn <i>→</i> Practice <i>→</i> Master</span></div></footer>; }

void SearchButton;
void Result;
